CREATE TABLE import_batches (id uuid PRIMARY KEY, owner_id text NOT NULL, idempotency_key text NOT NULL, atomic boolean NOT NULL, state text NOT NULL CHECK (state IN ('created', 'processing', 'completed', 'failed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id, idempotency_key));
CREATE TABLE idempotency_results (owner_id text NOT NULL, idempotency_key text NOT NULL, fingerprint char(64) NOT NULL CHECK (fingerprint ~ '^[0-9a-f]{64}$'), reservation_id uuid NOT NULL, status_code integer, response_body text, response_content_type text, reissue_response boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, PRIMARY KEY (owner_id, idempotency_key));
CREATE TABLE content_objects (sha256 char(64) PRIMARY KEY CHECK (sha256 ~ '^[0-9a-f]{64}$'), byte_length bigint NOT NULL CHECK(byte_length >= 0), category text NOT NULL, storage_key text NOT NULL UNIQUE, storage_version text, integrity_state text NOT NULL CHECK (integrity_state IN ('staging', 'pending-publication', 'authoritative', 'quarantined', 'integrity-error')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assets (id uuid PRIMARY KEY, owner_id text NOT NULL, original_sha256 char(64) REFERENCES content_objects(sha256), state text NOT NULL CHECK (state IN ('prepared', 'active', 'recoverable-deleted', 'restored', 'integrity-error')), lifecycle_version bigint NOT NULL DEFAULT 1 CHECK (lifecycle_version > 0), deleted_until timestamptz);
CREATE TABLE upload_sessions (id uuid PRIMARY KEY, batch_id uuid NOT NULL REFERENCES import_batches(id), owner_id text NOT NULL, target_key text NOT NULL UNIQUE, expected_sha256 char(64) NOT NULL CHECK (expected_sha256 ~ '^[0-9a-f]{64}$'), expected_length bigint NOT NULL CHECK(expected_length >= 0), received_parts jsonb NOT NULL DEFAULT '[]', state text NOT NULL CHECK (state IN ('uploading', 'verifying', 'completed', 'failed', 'cancelled')), expires_at timestamptz NOT NULL, lifecycle_version bigint NOT NULL DEFAULT 1 CHECK (lifecycle_version > 0));
CREATE TABLE import_batch_items (id uuid PRIMARY KEY, batch_id uuid NOT NULL REFERENCES import_batches(id), upload_session_id uuid NOT NULL UNIQUE REFERENCES upload_sessions(id), state text NOT NULL, outcome_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE edit_identities (id uuid PRIMARY KEY, asset_id uuid NOT NULL REFERENCES assets(id), duplicate_ordinal integer NOT NULL CHECK (duplicate_ordinal >= 0), xmp_sha256 char(64) REFERENCES content_objects(sha256), association_provenance text NOT NULL, UNIQUE(asset_id, duplicate_ordinal));
CREATE TABLE asset_paths (id uuid PRIMARY KEY, asset_id uuid NOT NULL REFERENCES assets(id), owner_id text NOT NULL, display_path text NOT NULL, collision_key text NOT NULL, active boolean NOT NULL, effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz);
CREATE UNIQUE INDEX active_asset_path_collision ON asset_paths (owner_id, collision_key) WHERE active;
CREATE TABLE lifecycle_holds (id uuid PRIMARY KEY, asset_id uuid NOT NULL REFERENCES assets(id), reason text NOT NULL, source_reference text NOT NULL, expires_at timestamptz);
CREATE TABLE publication_intents (id uuid PRIMARY KEY, state text NOT NULL CHECK (state IN ('pending-publication', 'publishing', 'published', 'reconciled', 'failed')), object_state text NOT NULL CHECK (object_state IN ('unverified', 'verified', 'promoted', 'failed')), payload jsonb NOT NULL, repair_evidence jsonb NOT NULL DEFAULT '{}', retry_count integer NOT NULL DEFAULT 0 CHECK (retry_count >= 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE publication_intent_items (intent_id uuid PRIMARY KEY REFERENCES publication_intents(id), asset_id uuid NOT NULL REFERENCES assets(id), content_sha256 char(64) NOT NULL REFERENCES content_objects(sha256), upload_session_id uuid NOT NULL REFERENCES upload_sessions(id));
CREATE TABLE audit_events (id uuid PRIMARY KEY, owner_id text NOT NULL, operation_id text NOT NULL, event_type text NOT NULL, outcome text NOT NULL, reason_code text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reconstruction_manifests (id uuid PRIMARY KEY, version integer NOT NULL CHECK (version > 0), inventory_sha256 char(64) NOT NULL CHECK (inventory_sha256 ~ '^[0-9a-f]{64}$'), inventory jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
